/** @description Owns the public greeting operation and its recoverable input failure. */

export type GreetingFailure = {
	readonly code: 'EMPTY_NAME';
	readonly message: string;
};

export type GreetingResult =
	| { readonly ok: true; readonly value: string }
	| { readonly ok: false; readonly error: GreetingFailure };

/** @description Creates a greeting without assuming how a caller obtained or normalized the name. */
export function createGreeting({ name }: { readonly name: string }): GreetingResult {
	const trimmedName = name.trim();

	if (trimmedName.length === 0) {
		return {
			ok: false,
			error: {
				code: 'EMPTY_NAME',
				message: 'A non-empty name is required.',
			},
		};
	}

	return { ok: true, value: `Hello, ${trimmedName}!` };
}

